"use strict";(()=>{const data=window.LEARNWITHUS_GAMES||[],sel=document.getElementById('gamesQuizSelect'),root=document.getElementById('gamesQuizRoot');if(!data.length||!root)return;data.forEach(g=>sel.add(new Option(g.emoji+' '+g.name,g.id)));const requested=new URLSearchParams(location.search).get('game')||'all';sel.value=[...sel.options].some(o=>o.value===requested)?requested:'all';const speak=t=>{if(!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='en-IN';u.rate=.82;speechSynthesis.speak(u)},shuffle=a=>[...a].sort(()=>Math.random()-.5);let questions=[],i=0,score=0,current='all';function build(){current=sel.value;let pool=current==='all'?data.flatMap(g=>g.examples.map(x=>({...x,topic:g.name}))):(data.find(g=>g.id===current)?.examples||[]).map(x=>({...x,topic:data.find(g=>g.id===current)?.name}));questions=shuffle(pool).slice(0,10);i=0;score=0;round();history.replaceState({},'',location.pathname+'?game='+current)}function finish(){const label=current==='all'?'All Learning Games':data.find(g=>g.id===current).name;root.innerHTML='<section class="practice-box"><p class="game-progress">Quiz complete</p><p class="game-question">'+score+' / 10</p><p class="game-feedback">'+(score>=8?'Excellent game skills!':'Good try. Practise more examples and try again.')+'</p><div id="sharedScoreCard"></div><div class="journey-actions"><button id="again" class="practice-button journey-primary">Play again</button><a class="practice-button" href="games.html'+(current==='all'?'':'?game='+current)+'">📖 Practise again</a></div></section>';window.renderLearnWithUsScoreCard?.({container:document.getElementById('sharedScoreCard'),score,total:10,title:label+' Quiz',subtitle:score>=8?'Great learning-game result!':'Practise and try again.',filename:'learnwithus-games-score.svg',url:'games-quiz.html?game='+current});window.LearnWithUs?.recordQuiz?.(label+' quiz',score,10,'games-quiz.html?game='+current);document.getElementById('again').onclick=build}function round(){if(i>=questions.length)return finish();const q=questions[i];root.innerHTML='<section class="practice-box"><p class="game-progress">Question '+(i+1)+' of 10 · '+q.topic+'</p><p class="game-question">'+q.q+'</p><div class="game-options" id="opts"></div><p class="game-feedback" id="fb" role="status"></p><button id="next" class="practice-button game-next" hidden>'+(i===9?'See score →':'Next →')+'</button></section>';const opts=document.getElementById('opts'),fb=document.getElementById('fb'),next=document.getElementById('next');shuffle(q.options).forEach(choice=>{const b=document.createElement('button');b.type='button';b.textContent=choice;b.onclick=()=>{const ok=choice===q.answer,msg=ok?'Correct answer!':'Wrong answer. The correct answer is '+q.answer+'.';opts.querySelectorAll('button').forEach(x=>{x.disabled=true;if(x.textContent===q.answer)x.classList.add('correct')});b.classList.add(ok?'correct':'wrong');if(ok)score++;fb.textContent=msg;speak(msg);next.hidden=false};opts.append(b)});next.onclick=()=>{i++;round()}}sel.addEventListener('change',build);build()})();